mapper.select:
SELECT * FROM ( SELECT r.*, u.username, l.name AS level_name, ROW_NUMBER() OVER (PARTITION BY r.user_id, r.level_id ORDER BY r.score DESC, r.wave DESC) AS rn FROM game_record r LEFT JOIN user u ON r.user_id = u.id LEFT JOIN level l ON r.level_id = l.id
r.level_id = #{levelId}
) t WHERE t.rn = 1 ORDER BY t.score DESC, t.wave DESC LIMIT 50
